bool json_parse_settings_section_with_len(const char *json_string, size_t json_string_len, settings_section_t *out) {
    parse_state_t parse_state_var;
    parse_state_t *parse_state = &parse_state_var;
    jsmntok_t token_buffer[19];
    if (builtin_parse_json_string(parse_state, token_buffer, 19, json_string, json_string_len)) {
        return true;
    }
    if (parse_settings_section(parse_state, out)) {
        return true;
    }
    return false;
}

bool json_parse_settings_section(const char *json_string, settings_section_t *out) {
    return json_parse_settings_section_with_len(json_string, strlen(json_string), out);
}
